// แยกรายการจากข้อความ เช่น "BR-6204:20, BT-B52:5" ราคาไม่รับจากโมเดล จะอ่านจากตาราง products เท่านั้น
const q = $json;
const items = [...String(q.items || '').matchAll(/([A-Za-z]{2}-[A-Za-z0-9]+)\s*[:x×=]\s*(\d+)/g)]
  .map(m => ({ sku: m[1].toUpperCase(), qty: Number(m[2]) }));
const errors = [];
if (!q.customer) errors.push('ไม่มีชื่อลูกค้า');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(q.email || '')) errors.push('อีเมลไม่ถูกต้อง');
if (items.length === 0) errors.push('ไม่มีรายการสินค้าในรูป รหัส:จำนวน');
return { json: { ...q, parsed: items, skus: items.map(i => i.sku).join(','), errors } };

// คำนวณใบเสนอราคาตามนโยบายเดียวกับ calculate_price ของบทที่ 5 ทีละบรรทัด
const q = $('แยกรายการ').item.json;
const prices = Object.fromEntries($input.all().filter(i => i.json.sku).map(i => [i.json.sku, i.json]));
const round2 = n => Math.round(n * 100) / 100;
const errors = [...q.errors];
const lines = [];
for (const it of q.parsed) {
  const p = prices[it.sku];
  if (!p) { errors.push(`ไม่พบรหัสสินค้า ${it.sku}`); continue; }
  const gross = round2(Number(p.price) * it.qty);
  const pct = it.qty >= 100 ? 10 : it.qty >= 50 ? 5 : 0;
  const net = round2(gross - gross * pct / 100);
  lines.push({ sku: it.sku, name: p.name, unit: p.unit, qty: it.qty, unit_price: Number(p.price),
               discount_percent: pct, net, in_stock: p.stock >= it.qty, stock: p.stock });
}
const net = round2(lines.reduce((s, l) => s + l.net, 0));
const vat = round2(net * 0.07);
return { json: { ok: errors.length === 0, errors, customer: q.customer, email: q.email, session_id: q.session_id,
                 lines, net, vat, total: round2(net + vat) } };

